function formatMemories(memories) {
    if (!memories || memories.length === 0)
        return '[]';
    return memories.map(m => ({
        id: m.id?.slice(0, 8),
        content: m.content?.length > 100 ? m.content.slice(0, 100) + '...' : m.content,
        type: m.type,
        imp: m.importance
    })).map(m => `[${m.id}] ${m.content} (${m.type}, imp:${m.imp})`).join('\n');
}
server.setRequestHandler(types_js_1.CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;
    const a = args;
    try {
        const result = await handleTool(name, a);
        autoMemory.processMessage('assistant', JSON.stringify(a));
        return result;
    }
    catch (error) {
        autoMemory.processMessage('assistant', `Error: ${error}`);
        throw error;
    }
});
async function handleTool(name, a) {
    switch (name) {
        case 'recall': {
            autoMemory.processMessage('user', a.query);
            const memories = await searchEngine.search({ query: a.query, limit: 5 });
            if (memories.length === 0) {
                return { content: [{ type: 'text', text: '📚 无相关记忆' }] };
            }
            const formatted = memories.map(m => `• ${m.content}${m.importance > 0 ? ` [重要${m.importance}]` : ''}`).join('\n');
            return { content: [{ type: 'text', text: `📚 相关记忆：\n${formatted}` }] };
        }
        case 'memory': {
