                    switch (a.list_type) {
                        case 'project':
                            memories = memoryManager.getProjectMemories(a.project_path);
                            break;
                        case 'recent':
                            memories = memoryManager.getRecentMemories(a.hours || 24);
                            break;
                        case 'important':
                            memories = memoryManager.getImportantMemories();
                            break;
                        case 'long_term':
                            memories = memoryManager.getLongTermMemories();
                            break;
                        default: memories = memoryManager.getAllMemories();
                    }
                    const limited = memories.slice(0, a.limit || 10);
                    return { content: [{ type: 'text', text: formatMemories(limited) }] };
                }
                case 'mark': {
