                    return { content: [{ type: 'text', text: ok ? '✓ 已失效' : '未找到' }] };
                }
                case 'clear': {
                    memoryManager.clearAllMemories();
                    return { content: [{ type: 'text', text: '✓ 已清空所有记忆（保留默认设置）' }] };
