                    if (!s)
                        s = { id: graphManager.addEntity(a.subject) };
                    let o = graphManager.getEntityByName(a.object);
                    if (!o)
                        o = { id: graphManager.addEntity(a.object) };
                    const id = graphManager.addRelation(s.id, a.predicate, o.id);
                    return { content: [{ type: 'text', text: `✓ 已添加关系 [${id.slice(0, 8)}]` }] };
                }
                case 'query': {
